const D = { density: .58, energy: .72, scale: 1, speed: 1, warp: .55, hue: 280, x: .5, y: .5, style: 'neon-rosette', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const diag = Math.hypot(width, height);
const style = P.style;
const glow = (style === 'neon-rosette' || style === 'gold-guilloche');

function hcss(h, s, b, a) {
  h = wh(h); s /= 100; b /= 100;
  const c = b * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = b - c;
  let r, g2, bl;
  if (h < 60) { r = c; g2 = x; bl = 0; } else if (h < 120) { r = x; g2 = c; bl = 0; }
  else if (h < 180) { r = 0; g2 = c; bl = x; } else if (h < 240) { r = 0; g2 = x; bl = c; }
  else if (h < 300) { r = x; g2 = 0; bl = c; } else { r = c; g2 = 0; bl = x; }
  return 'rgba(' + ((r + m) * 255 | 0) + ',' + ((g2 + m) * 255 | 0) + ',' + ((bl + m) * 255 | 0) + ',' + a + ')';
}

// ----- pen count from density (4..7 roulettes) -----
const NP = Math.max(4, Math.min(7, 4 + Math.round(P.density * 3)));

// ----- seed / pen-count rebuild (inline hash, NOT p5 random) -----
if (S.seedUsed !== P.seed || S.NP !== NP) {
  S.seedUsed = P.seed; S.NP = NP;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.pen = [];
  for (let k = 0; k < NP; k++) {
    const p = 3 + Math.floor(fr(k * 9 + 1) * 5);            // petal integer 3..7
    S.pen.push({
      p,
      type: fr(k * 9 + 2) < 0.45 ? 1 : -1,                 // +1 epitrochoid / -1 hypotrochoid
      B: 0.34 + fr(k * 9 + 3) * 0.6,                       // pen-hole distance ratio (dense rosette)
      d0: 0.02 + fr(k * 9 + 4) * 0.035,                    // base ratio detune (keeps figure open)
      turns: 26 + Math.floor(fr(k * 9 + 5) * 22),          // base windings (many loops)
      oa: fr(k * 9 + 6) * TAU,                             // center scatter angle
      orr: 0.03 + fr(k * 9 + 7) * 0.15,                    // center scatter radius (*u)
      hoff: (k / NP) * 300 + fr(k * 9 + 8) * 44,           // hue spread around wheel
      dir: fr(k * 9 + 3) < 0.5 ? 1 : -1,
      dph: fr(k * 9 + 2) * TAU,
      bph: fr(k * 9 + 5) * TAU,
      _f: 0, _Bl: 0, _norm: 0, _inner: 1, _cr: 1, _sr: 0, _pcx: 0, _pcy: 0, _hue: 0
    });
  }
  S.hoff2 = (fr(701) - 0.5) * 40;
  S.PX = new Float32Array(2200); S.PY = new Float32Array(2200);
}

// ----- full-canvas render buffer (cached on size) -----
if (!S.fb || S.fbKey !== width + 'x' + height) {
  S.fb = createGraphics(width, height); S.fb.pixelDensity(1);
  S.fb.colorMode(HSB, 360, 100, 100, 100); S.fbKey = width + 'x' + height;
}
const g = S.fb;

// ----- radial glow sprite (grayscale, built once) -----
if (!S.rg) {
  const RG = 200; S.rg = createGraphics(RG, RG); S.rg.pixelDensity(1); S.rg.noStroke();
  const gc = S.rg.drawingContext;
  const grd = gc.createRadialGradient(RG / 2, RG / 2, RG * 0.02, RG / 2, RG / 2, RG * 0.5);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.32, 'rgba(150,150,150,1)');
  grd.addColorStop(1, 'rgba(4,4,4,1)');
  gc.fillStyle = grd; gc.fillRect(0, 0, RG, RG);
}

// ----- live parameters (all rhythm from K; linear-in-K.t drift never re-phases) -----
const sec = K.section;
const isec = 0.4 + 0.6 * K.intensity;
const hb = wh(P.hue + S.hoff2 + sec * 15);                 // palette drifts across the arc
const eg = 0.45 + P.energy * 0.9;
const cx = width * P.x, cy = height * P.y;
const baseR = diag * 0.5 * (0.30 + P.scale * 0.40);        // reach toward the corners
const prec = K.t * (0.04 + P.speed * 0.06);                // global precession
const buildF = 0.5 + 0.5 * Math.min(1, sec / 4 + K.intensity * 0.5); // dramaturgy: extra flowers bloom in

// ================= GROUND =================
g.push();
if (style === 'pastel-spiro') g.background(wh(hb + 20), 12, 92);
else if (style === 'ink') g.background(38, 12, 90);
else if (style === 'blueprint') g.background(214, 80, 17);
else if (style === 'gold-guilloche') g.background(34, 60, 6);
else g.background(wh(hb), 62, 8);
g.pop();

// ================= AMBIENT AURA (lift midtones / bloom) =================
const cov = Math.max(width, height) * 1.6;
g.push(); g.imageMode(CENTER);
if (style === 'pastel-spiro' || style === 'ink') {
  g.blendMode(MULTIPLY); g.tint(wh(hb), 10, 100); g.image(S.rg, cx, cy, cov * 1.3, cov * 1.3); g.blendMode(BLEND);
} else if (style === 'blueprint') {
  g.blendMode(ADD); g.tint(205, 55, 22 * (0.7 + 0.4 * isec)); g.image(S.rg, cx, cy, cov, cov); g.blendMode(BLEND);
} else {
  g.blendMode(ADD);
  const ah = style === 'gold-guilloche' ? 40 : wh(hb + 10);
  const asat = style === 'gold-guilloche' ? 68 : 58;
  g.tint(ah, asat, (style === 'gold-guilloche' ? 26 : 34) * (0.7 + 0.5 * isec) + A.rms * 22);
  g.image(S.rg, cx, cy, cov, cov);
  g.blendMode(BLEND);
}
g.pop();

// ================= ROULETTE FLOWERS =================
const Ncap = Math.min(1400, Math.round(5200 / NP));
for (let k = 0; k < NP; k++) {
  const pen = S.pen[k];
  const drift = (0.008 + P.warp * 0.05) * Math.sin(K.t * (0.03 + 0.02 * k) + pen.dph) + A.bass * 0.04;
  const f = pen.p + pen.d0 + drift;                        // drifting ratio -> blooms / re-patterns
  const Bl = pen.B * (0.85 + 0.28 * Math.sin(K.t * 0.09 + pen.bph)); // pen distance breathes
  const norm = baseR / (1 + Bl);
  const rotk = prec * pen.dir + pen.dph * 0.1;
  const cr = Math.cos(rotk), sr = Math.sin(rotk);
  const orbA = pen.oa + prec * 0.25 * pen.dir;
  const pcx = cx + Math.cos(orbA) * pen.orr * u;
  const pcy = cy + Math.sin(orbA) * pen.orr * u;
  const inner = pen.type;
  let N = Math.round(pen.turns * (5 + pen.p * 3) * (0.7 + 0.5 * P.density));
  N = Math.max(240, Math.min(Ncap, N));
  for (let i = 0; i <= N; i++) {
    const t = (i / N) * TAU * pen.turns;
    const bx = Math.cos(t) + Bl * Math.cos(f * t);
    const by = Math.sin(t) + inner * Bl * Math.sin(f * t);
    const vx = bx * norm, vy = by * norm;
    S.PX[i] = pcx + vx * cr - vy * sr;
    S.PY[i] = pcy + vx * sr + vy * cr;
  }
  const hue = wh(hb + pen.hoff + prec * 16 * pen.dir);
  const penVis = k < 3 ? 1 : (0.5 + 0.5 * buildF);         // later flowers build in over the arc
  pen._f = f; pen._Bl = Bl; pen._norm = norm; pen._inner = inner; pen._cr = cr; pen._sr = sr; pen._pcx = pcx; pen._pcy = pcy; pen._hue = hue;

  if (glow) {
    g.blendMode(ADD); g.noStroke();
    g.fill(hue, style === 'gold-guilloche' ? 62 : 74, 55, (style === 'gold-guilloche' ? 4 : 6) * eg * penVis);
    g.beginShape(); for (let i = 0; i <= N; i += 6) g.vertex(S.PX[i], S.PY[i]); g.endShape(CLOSE);
    g.noFill();
    const wG = (style === 'gold-guilloche' ? 3.2 : 5.5) * (0.6 + eg * 0.6);
    g.stroke(hue, style === 'gold-guilloche' ? 64 : 82, 100, (style === 'gold-guilloche' ? 7 : 8) * penVis);
    g.strokeWeight(wG);
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
    g.drawingContext.shadowBlur = (style === 'gold-guilloche' ? 7 : 13) * (0.5 + eg);
    g.drawingContext.shadowColor = hcss(hue, style === 'gold-guilloche' ? 60 : 74, 100, 0.85);
    g.stroke(wh(hue + (style === 'gold-guilloche' ? 4 : 8)), style === 'gold-guilloche' ? 70 : 52, 100, (style === 'gold-guilloche' ? 50 : 42) * Math.min(1, penVis + 0.15));
    g.strokeWeight(style === 'gold-guilloche' ? 0.9 : 1.3);
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
    g.drawingContext.shadowBlur = 0;
  } else if (style === 'blueprint') {
    g.blendMode(BLEND); g.noFill();
    g.stroke(200, 42, 100, 15); g.strokeWeight(0.7);
    g.ellipse(pcx, pcy, norm * (1 + Bl) * 2, norm * (1 + Bl) * 2);
    g.ellipse(pcx, pcy, norm * Math.abs(1 - Bl) * 2, norm * Math.abs(1 - Bl) * 2);
    g.stroke(wh(200 + 8 * Math.sin(k)), 30, 100, 48 * penVis); g.strokeWeight(1.0);
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
  } else if (style === 'pastel-spiro') {
    g.blendMode(BLEND); g.noFill();
    g.stroke(wh(hue), 26, 96, 20 * penVis); g.strokeWeight(3.2 * (0.7 + eg * 0.5));
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
    g.stroke(wh(hue + 6), 42, 90, 34 * penVis); g.strokeWeight(1.3);
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
  } else {
    g.blendMode(BLEND); g.noFill();
    const dry = 0.5 + 0.5 * Math.sin(k * 1.7 + pen.bph);
    g.stroke(28, 22, 12, 40 + 30 * dry); g.strokeWeight(0.8 + 1.6 * dry);
    g.beginShape(); for (let i = 0; i <= N; i++) g.vertex(S.PX[i], S.PY[i]); g.endShape();
  }
}
g.blendMode(BLEND);

// ================= COMPOSITE (tint carries VJ alpha; no bg clear) =================
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);

// ================= AUDIO SPARKLE PENS (on top; baseline-independent) =================
if (glow && (A.treble > 0.02 || A.rms > 0.02 || K.pulse > 0.02)) {
  push(); blendMode(ADD); noStroke();
  const th = K.t * (0.5 + P.speed * 0.6);
  for (let k = 0; k < NP; k++) {
    const pen = S.pen[k];
    const a = th * pen.dir + pen.dph;
    const bx = Math.cos(a) + pen._Bl * Math.cos(pen._f * a);
    const by = Math.sin(a) + pen._inner * pen._Bl * Math.sin(pen._f * a);
    const vx = bx * pen._norm, vy = by * pen._norm;
    const hx = pen._pcx + vx * pen._cr - vy * pen._sr;
    const hy = pen._pcy + vx * pen._sr + vy * pen._cr;
    drawingContext.shadowBlur = 8 + A.rms * 20;
    drawingContext.shadowColor = 'rgba(220,235,255,0.7)';
    fill(wh(pen._hue + 20), 30, 100, 80);
    circle(hx, hy, 3 + A.treble * 8 + K.pulse * 2);
  }
  drawingContext.shadowBlur = 0;
  blendMode(BLEND); pop();
}
